import app from 'flarum/forum/app';
import FormModal from 'flarum/common/components/FormModal';
import Button from 'flarum/common/components/Button';
import Stream from 'flarum/common/utils/Stream';
import { browserZone, call, t } from '../api';
import PlaceSearch from './PlaceSearch';

/**
 * Plan a meetup: a title, a place, a time (local to the place) and a few
 * words. It starts a discussion to talk it through, shows as a pin, and goes
 * on the calendar when the Calendar extension is installed.
 */

const tm = (key, params = {}) => t(`meetup.${key}`, params);
export default class MeetupModal extends FormModal {
  name = Stream('');
  place = null;
  when = Stream('');
  details = Stream('');
  className() {
    return 'MemberMapMeetupModal Modal--small';
  }
  title() {
    return tm('title');
  }
  content() {
    return m("div", {
      className: "Modal-body"
    }, m("div", {
      className: "Form"
    }, m("div", {
      className: "Form-group"
    }, m("label", {
      for: "member-map-meetup-title"
    }, tm('name')), m("input", {
      id: "member-map-meetup-title",
      className: "FormControl",
      maxLength: 80,
      bidi: this.name,
      placeholder: tm('name_placeholder'),
      required: true
    })), m(PlaceSearch, {
      id: "member-map-meetup-place",
      label: tm('where'),
      onpick: place => this.place = place
    }), m("div", {
      className: "Form-group"
    }, m("label", {
      for: "member-map-meetup-when"
    }, tm('when')), m("input", {
      id: "member-map-meetup-when",
      className: "FormControl",
      type: "datetime-local",
      bidi: this.when,
      required: true
    }), m("p", {
      className: "helpText"
    }, tm('when_help'))), m("div", {
      className: "Form-group"
    }, m("label", {
      for: "member-map-meetup-details"
    }, tm('details')), m("textarea", {
      id: "member-map-meetup-details",
      className: "FormControl",
      rows: 4,
      maxLength: 2000,
      bidi: this.details,
      placeholder: tm('details_placeholder')
    })), m("div", {
      className: "Form-group"
    }, m(Button, {
      className: "Button Button--primary Button--block",
      type: "submit",
      loading: this.loading,
      disabled: !this.place || this.name().trim().length < 3 || !this.when()
    }, tm('save')))));
  }
  onsubmit(e) {
    e.preventDefault();
    if (!this.place) return;
    this.loading = true;
    call('POST', '/meetups', {
      title: this.name().trim(),
      details: this.details().trim(),
      lat: this.place.lat,
      lng: this.place.lng,
      startsAt: this.when().slice(0, 16),
      timezone: browserZone()
    }).then(({
      meetup
    }) => {
      app.alerts.show({
        type: 'success'
      }, tm('saved'));
      this.attrs.onsave?.();
      this.hide();
      m.route.set(app.route('discussion', {
        id: `${meetup[7]}-${meetup[8]}`
      }));
    }).catch(() => {}).finally(() => {
      this.loading = false;
      m.redraw();
    });
  }
}
flarum.reg.add('ernestdefoe-member-map', 'forum/components/MeetupModal', MeetupModal);